# ============================================================
# 05_comparisons.R
# ============================================================
# Purpose:
#   Compare the country rankings generated by the alternative
#   composite-index specifications.
#
#
# Main analyses:
#   1. Country rankings under AM, GM, Ch_const and Ch_corr.
#   2. Kendall rank correlations.
#   3. Number and percentage of ranking changes.
#   4. Magnitude of rank movements.
#   5. Distribution of absolute rank changes (Figure 3).
#   6. Stability/overlap across the specified development groups.
#
# Manuscript outputs explicitly identified in the original code:
#   Table 8  - ranking concordance and ranking changes.
#   Figure 3 - distributions/boxplots of absolute rank changes.
#   Table 9  - overlap/stability across development groups.
#
# Additional objects are retained in the script to allow the
# reviewer to inspect the largest ranking changes and potential
# outliers.

# Outputs:
#   output/05_comparisons/indices_rankings.csv
#   output/05_comparisons/rankings.csv
#   output/05_comparisons/kendall_correlations.tex
#   output/05_comparisons/rank_changes.tex
#   output/05_comparisons/figure_rank_changes_journal.pdf
#   output/05_comparisons/rank_change_outliers.csv
#   output/05_comparisons/stability_table.tex
#   output/05_comparisons/stability_table.csv
# ============================================================

# ------------------------------------------------------------
# DIRECTORY TO SAVE RESULTS
# ------------------------------------------------------------
out_dir <- "output/05_comparisons"
# ------------------------------------------------------------
# CREATE COUNTRY RANKINGS
# ------------------------------------------------------------
# Lower numerical rank means a higher position in the ranking.
# ties.method = "max" reproduces the original ranking rule.
# ------------------------------------------------------------

indices$r_am <- rank(desc(indices$am), ties.method = "max")
indices$r_gm <- rank(desc(indices$gm), ties.method = "max")
indices$r_ch_const <- rank(desc(indices$ch_const), ties.method = "max")
indices$r_ch_corr <- rank(desc(indices$ch_corr), ties.method = "max")

# Save the complete ranking dataset before retaining only the
# ranking variables used in the comparisons.
write.csv(
  indices,
  file.path(out_dir,"indices_rankings.csv"),
  row.names = FALSE
)

# Retain only rankings
rankings <- indices[, -c(2:5)]
# ============================================================
# MANUSCRIPT OUTPUT: TABLE 10
# ============================================================
# Use the rankings data frame to identify an illustrative
# example of a ranking reversal between Fiji and the Maldives.

write.csv(
  rankings,
  file.path(out_dir,"rankings.csv"),
  row.names = FALSE
)

# ============================================================
# MANUSCRIPT OUTPUT: TABLE 8, COLUMN 1
# ============================================================
# Kendall rank correlations measure concordance between the
# country rankings generated by the different aggregation
# functions.
# ============================================================

cor_rank <- cor(
  rankings[sapply(rankings, is.numeric)],
  method = "kendall",
  use = "pairwise.complete.obs"
)

print(
  xtable(cor_rank, digits = 4),
  type = "latex",
  file = file.path(out_dir, "kendall_correlations.tex")
)

# ============================================================
# MANUSCRIPT OUTPUT: TABLE 8, COLUMNS 2 AND 3
# ============================================================
# For each pair of aggregation functions, calculate the number
# and percentage of countries whose rank changes.
# ============================================================

rank_pairs <- list(
  c("r_am", "r_gm"),
  c("r_am", "r_ch_const"),
  c("r_am", "r_ch_corr"),
  c("r_gm", "r_ch_const"),
  c("r_gm", "r_ch_corr"),
  c("r_ch_const", "r_ch_corr")
)

rank_change_summary <- function(r1, r2) {
  diff <- rankings[[r1]] - rankings[[r2]]
  c(
    n_changed = sum(diff != 0),
    pct_changed = mean(diff != 0) * 100
  )
}

rank_changes <- t(sapply(rank_pairs, function(p) {
  rank_change_summary(p[1], p[2])
}))

rownames(rank_changes) <- sapply(rank_pairs, paste, collapse = " vs ")

print(
  xtable(rank_changes, digits = 4),
  type = "latex",
  file = file.path(out_dir, "rank_changes.tex")
)

# ============================================================
# RANK MOVEMENTS AND EXAMPLES OF LARGE CHANGES
# ============================================================
# Calculate absolute differences between rankings. These objects
# allow the reviewer to identify countries with the largest
# changes between aggregation specifications.
# ============================================================

rankings$abs_diff_gm_am <- abs(rankings$r_gm - rankings$r_am)
rankings$abs_diff_am_ch_const <- abs(rankings$r_am - rankings$r_ch_const)
rankings$abs_diff_am_ch_corr <- abs(rankings$r_am - rankings$r_ch_corr)
rankings$abs_diff_gm_ch_const <- abs(rankings$r_gm - rankings$r_ch_const)
rankings$abs_diff_gm_ch_corr <- abs(rankings$r_gm - rankings$r_ch_corr)
rankings$abs_diff_ch_const_ch_corr <- abs(rankings$r_ch_const - rankings$r_ch_corr)

# Sorted country-level tables are retained as intermediate objects
# for inspection of the largest ranking movements.
tablc_am_gm <- rankings %>%
  select(Country, r_am, r_gm, abs_diff_gm_am) %>%
  arrange(desc(abs_diff_gm_am))

tablc_am_ch_const <- rankings %>%
  select(Country, r_am, r_ch_const, abs_diff_am_ch_const) %>%
  arrange(desc(abs_diff_am_ch_const))

tablc_am_ch_corr <- rankings %>%
  select(Country, r_am, r_ch_corr, abs_diff_am_ch_corr) %>%
  arrange(desc(abs_diff_am_ch_corr))

tablc_gm_ch_const <- rankings %>%
  select(Country, r_gm, r_ch_const, abs_diff_gm_ch_const) %>%
  arrange(desc(abs_diff_gm_ch_const))

tablc_gm_ch_corr <- rankings %>%
  select(Country, r_gm, r_ch_corr, abs_diff_gm_ch_corr) %>%
  arrange(desc(abs_diff_gm_ch_corr))

tablc_ch_const_ch_corr <- rankings %>%
  select(Country, r_ch_const, r_ch_corr, abs_diff_ch_const_ch_corr) %>%
  arrange(desc(abs_diff_ch_const_ch_corr))

# ============================================================
# MANUSCRIPT OUTPUT: FIGURE 3
# ============================================================
# Figure 3 displays the distributions of absolute ranking
# changes across selected pairs of aggregation specifications.
# Panel A contains histograms and Panel B contains boxplots.
# Generated file:
#   output/05_comparisons/figure_rank_changes_journal.pdf
# ============================================================

theme_journal <- function() {
  theme_minimal(base_size = 9) +
    theme(
      panel.grid.major = element_line(linewidth = 0.2),
      panel.grid.minor = element_blank(),
      axis.text = element_text(color = "black", size = 8),
      axis.title = element_text(size = 9),
      strip.text = element_text(size = 8),
      panel.spacing.y = unit(1.5, "lines"),
      panel.spacing.x = unit(1.2, "lines"),
      legend.position = "none"
    )
}

diff_rankings <- rankings %>%
  select(
    abs_diff_gm_am,
    abs_diff_gm_ch_const,
    abs_diff_gm_ch_corr,
    abs_diff_ch_const_ch_corr
  ) %>%
  pivot_longer(
    cols = everything(),
    names_to = "comparison",
    values_to = "abs_diff"
  ) %>%
  mutate(
    comparison = factor(
      comparison,
      levels = c(
        "abs_diff_gm_am",
        "abs_diff_gm_ch_const",
        "abs_diff_gm_ch_corr",
        "abs_diff_ch_const_ch_corr"
      ),
      labels = c(
        "GM-AM",
        "GM-Ch_const",
        "GM-Ch_corr",
        "Ch_const-Ch_corr"
      )
    )
  )
# Labels with mathematical notation
comparison_labels <- c(
  "GM-AM" = expression(G[eta] - A[eta]),
  "GM-Ch_const" = expression(G[eta] - C[mu[1]]),
  "GM-Ch_corr" = expression(G[eta] - C[mu[2]]),
  "Ch_const-Ch_corr" = expression(C[mu[1]] - C[mu[2]])
)



# Panel A: histograms.
pA <- ggplot(diff_rankings, aes(x = abs_diff)) +
  geom_histogram(
    #bins = 20,
    binwidth = 1,
    fill = "grey85",
    color = "black",
    linewidth = 0.2
  ) +
  facet_wrap(
    ~ comparison,
    ncol = 2,
    labeller = labeller(
      comparison = c(
        "GM-AM" = "G[eta]-A[eta]",
        "GM-Ch_const" = "G[eta]-C[mu[1]]",
        "GM-Ch_corr" = "G[eta]-C[mu[2]]",
        "Ch_const-Ch_corr" = "C[mu[1]]-C[mu[2]]"
      ),
      .default = label_parsed
    )
  )+
  labs(
    x = "Absolute rank change",
    y = "Frequency"
  ) +
  theme_journal()

# Panel B: boxplots.
pB <- ggplot(diff_rankings, aes(x = fct_rev(comparison), y = abs_diff)) +
  geom_boxplot(
    fill = "grey80",
    color = "black",
    linewidth = 0.3,
    outlier.size = 0.6
  ) +
  coord_flip() +
  scale_x_discrete(
    labels = comparison_labels
  ) +
  labs(
    x = "",
    y = "Absolute rank change"
  ) +
  theme_journal()

final_plot <- (pA | pB) +
  theme(
    plot.tag.position = "top",
    plot.tag = element_text(hjust = 0.5, size = 12, margin = margin(b = 15) ),
    plot.margin = margin(t = 5, r = 10, b = 5, l = 10)
  )

final_plot

ggsave(
  file.path(out_dir, "figure_rank_changes_journal.pdf"),
  final_plot,
  width = 7.2,
  height = 4.8
)

# ------------------------------------------------------------
# OUTLIER IDENTIFICATION FOR REVIEW/INSPECTION
# ------------------------------------------------------------
# Tukey's 1.5*IQR rule is used only to identify observations
# outside the boxplot whiskers in the GM-Ch_const and GM-Ch_corr
# comparisons. This does not alter the underlying ranking data.
# Generated file:
#   output/05_comparisons/rank_change_outliers.csv
# ------------------------------------------------------------

plot_rankings <- rankings %>%
  select(Country, abs_diff_gm_ch_const, abs_diff_gm_ch_corr) %>%
  pivot_longer(
    cols = starts_with("abs_diff_gm"),
    names_to = "comparison",
    values_to = "abs_diff"
  ) %>%
  mutate(
    comparison = factor(
      comparison,
      levels = c("abs_diff_gm_ch_const", "abs_diff_gm_ch_corr"),
      labels = c("GM-Ch_const", "GM-Ch_corr")
    )
  )

outliers <- plot_rankings %>%
  group_by(comparison) %>%
  group_modify(~ {
    x <- .x$abs_diff
    q1 <- quantile(x, 0.25, na.rm = TRUE)
    q3 <- quantile(x, 0.75, na.rm = TRUE)
    iqr <- q3 - q1
    lower <- q1 - 1.5 * iqr
    upper <- q3 + 1.5 * iqr

    .x %>%
      filter(abs_diff < lower | abs_diff > upper)
  }) %>%
  ungroup()

table_outliers <- outliers %>%
  arrange(desc(abs_diff)) %>%
  select(Country, comparison, abs_diff)

write.csv(
  table_outliers,
  file.path(out_dir, "rank_change_outliers.csv"),
  row.names = FALSE
)

# ============================================================
# MANUSCRIPT OUTPUT: TABLE 9
# ============================================================
# Measure the coincidence/overlap between rankings within the
# development groups defined by the original analysis:
#   1-74    Very high human development
#   75-124  High human development
#   125-167 Medium human development
#   168-193 Low human development
#
# The geometric-mean ranking is retained as the benchmark
# comparison, while the two Choquet specifications are compared
# with each other to assess the role of the interaction model.
#
# Generated files:
#   output/05_comparisons/stability_table.tex
#   output/05_comparisons/stability_table.csv
# ============================================================

topN_overlap <- function(r1, r2, N) {
  top1 <- rankings$Country[rankings[[r1]] <= N]
  top2 <- rankings$Country[rankings[[r2]] <= N]
  length(intersect(top1, top2)) / N
}

overlap_range <- function(r1, r2, lower, upper) {
  group1 <- rankings$Country[rankings[[r1]] >= lower & rankings[[r1]] <= upper]
  group2 <- rankings$Country[rankings[[r2]] >= lower & rankings[[r2]] <= upper]
  length(intersect(group1, group2)) / (upper - lower + 1)
}

Stab_vhhd <- data.frame(
  gm_vs_am = topN_overlap("r_gm", "r_am", 74),
  gm_vs_ch_const = topN_overlap("r_gm", "r_ch_const", 74),
  gm_vs_ch_corr = topN_overlap("r_gm", "r_ch_corr", 74),
  ch_const_vs_ch_corr = topN_overlap("r_ch_const", "r_ch_corr", 74)
)

Stab_hhd <- data.frame(
  gm_vs_am = overlap_range("r_gm", "r_am", 75, 124),
  gm_vs_ch_const = overlap_range("r_gm", "r_ch_const", 75, 124),
  gm_vs_ch_corr = overlap_range("r_gm", "r_ch_corr", 75, 124),
  ch_const_vs_ch_corr = overlap_range("r_ch_const", "r_ch_corr", 75, 124)
)

Stab_mhd <- data.frame(
  gm_vs_am = overlap_range("r_gm", "r_am", 125, 167),
  gm_vs_ch_const = overlap_range("r_gm", "r_ch_const", 125, 167),
  gm_vs_ch_corr = overlap_range("r_gm", "r_ch_corr", 125, 167),
  ch_const_vs_ch_corr = overlap_range("r_ch_const", "r_ch_corr", 125, 167)
)

Stab_lhd <- data.frame(
  gm_vs_am = overlap_range("r_gm", "r_am", 168, 193),
  gm_vs_ch_const = overlap_range("r_gm", "r_ch_const", 168, 193),
  gm_vs_ch_corr = overlap_range("r_gm", "r_ch_corr", 168, 193),
  ch_const_vs_ch_corr = overlap_range("r_ch_const", "r_ch_corr", 168, 193)
)

Stab_all <- rbind(
  data.frame(Group = "Very high human development", Stab_vhhd),
  data.frame(Group = "High human development", Stab_hhd),
  data.frame(Group = "Medium human development", Stab_mhd),
  data.frame(Group = "Low human development", Stab_lhd)
)

print(
  xtable(Stab_all),
  include.rownames = FALSE,
  type = "latex",
  file = file.path(out_dir, "stability_table.tex")
)

write.csv(
  Stab_all,
  file.path(out_dir, "stability_table.csv"),
  row.names = FALSE
)


message("Ranking comparisons completed successfully.")
